from pyvkteamsclient.client.base.client import BaseClient
from pyvkteamsclient.client.decorators import api_version_check
from pyvkteamsclient.tracer import tracer


class SurveysMethods(BaseClient):
    """
    Методы группы 'Опросы про' из https://im-docs.corp.mail.ru/
    """

    @api_version_check(min_version=88)
    @tracer.start_as_current_span("surveys.rapi_survey_begin")
    def rapi_survey_begin(self, survey_id: str):
        """
        Начать прохождение/пройти еще раз - удаляет всю историю голосования
        пользователя,
        начинает фиксировать прохождение Опрос Про как первый раз.
        """
        return self.post(
            "rapi/survey/begin",
            headers={"Content-Type": "application/json"},
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {"surveyId": survey_id},
            },
        )

    @api_version_check(min_version=88)
    @tracer.start_as_current_span("surveys.rapi_survey_vote")
    def rapi_survey_vote(self, survey_id: str, question_id: str, value):
        """
        Проголосовать/переголосовать (покрывает и revoke)
        по данному опросу на конкретный вопрос.
        """
        return self.post(
            "rapi/survey/vote",
            headers={"Content-Type": "application/json"},
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {
                    "surveyId": survey_id,
                    "questionId": question_id,
                    "value": value,
                },
            },
        )

    @api_version_check(min_version=88)
    @tracer.start_as_current_span("surveys.rapi_survey_get")
    def rapi_survey_get(self, survey_id: str):
        """
        Получение всей имеющейся информации об опросе.
        """
        return self.post(
            "rapi/survey/get",
            headers={"Content-Type": "application/json"},
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {"surveyId": survey_id},
            },
        )
